const DEFAULT_CATEGORIES=['蔬菜','肉類','水果','飲料','零食','米/麵/泡麵/麵包','雞蛋','牛奶','咖啡','外食','冷凍食品','日用品','調味料','保健食品','房租','住宅','交通','個人消費','GST','PST'];
const PALETTE=['#b9a5d4','#e4b8c5','#c9d6bd','#c7c5df','#e6d2b6','#b8cfd7','#e2c8df','#cbc4b8'];
const CAT_META={'蔬菜':['🥬','#edf2e5'],'肉類':['🥩','#f6e8e8'],'外食':['🍜','#f6e9df'],'咖啡':['☕','#efebe6'],'飲料':['🥤','#eee8f5'],'零食':['🍪','#f5ebdf'],'房租':['⌂','#eeebf7'],'住宅':['⌂','#eeebf7'],'日用品':['🧴','#e9eef2'],'交通':['↗','#e7edf4'],'水果':['🍋','#f4f0d9'],'牛奶':['🥛','#f0eddf'],'雞蛋':['🥚','#f4eede'],'個人消費':['♡','#f8e8ee'],'GST':['%','#eeeaf3'],'PST':['%','#eeeaf3']};
const PAGE_INFO={overview:['OUR LITTLE LIFE','我們的小日子','每一筆日常，都在往喜歡的生活靠近。','日常總覽'],records:['THE EVERYDAY DETAILS','把日常記清楚','吃的、用的、一起的，每一筆都有自己的位置。','收支明細'],calendar:['LITTLE DAYS, LITTLE ENTRIES','日子裡的每一筆','換個角度，看看這個月的生活軌跡。','記帳月曆'],settlement:['BETTER, TOGETHER','兩個人，剛剛好','你先付的、我先付的，這裡幫我們算清楚。','兩人分帳'],year:['A YEAR OF OUR LITTLE LIFE','回頭看，也走了好遠','把一年的小日常，放在一起看看。','年度回顧'],settings:['MAKE IT YOURS','我們的帳本設定','好好備份，也讓帳本更像我們。','設定與備份']};
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,extra='')=>`<svg class="icon ${extra}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const money=n=>new Intl.NumberFormat('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0);
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
const sum=(arr,fn)=>arr.reduce((n,item)=>n+fn(item),0);
const total=e=>LedgerModel.total(e);
const localDate=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const monthKey=()=>`${ui.year}-${String(ui.month).padStart(2,'0')}`;
const inMonth=record=>record.date.startsWith(monthKey()+'-');
function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number(value.slice(0,4))<1900||Number(value.slice(0,4))>2199)return false;const d=new Date(value+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===value;}
function parseAmount(value){
  const text=String(value??'').trim();if(!text||text.length>100||!/^[\d\s.+*/()\-]+$/.test(text))return null;
  const tokens=text.match(/(?:\d*\.\d+|\d+\.?\d*)|[()+*/-]/g)||[];let i=0;
  function factor(){const token=tokens[i++];if(token==='+')return factor();if(token==='-')return -factor();if(token==='('){const n=expression();if(tokens[i++]!==')')throw Error();return n;}if(token===undefined||!/^(?:\d*\.\d+|\d+\.?\d*)$/.test(token))throw Error();return Number(token);}
  function term(){let n=factor();while(tokens[i]==='*'||tokens[i]==='/'){const op=tokens[i++],right=factor();n=op==='*'?n*right:n/right;}return n;}
  function expression(){let n=term();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++],right=term();n=op==='+'?n+right:n-right;}return n;}
  try{const n=expression();return i===tokens.length&&Number.isFinite(n)&&Math.abs(n)<=1e10?Math.round(n*10000)/10000:null;}catch{return null;}
}
function makeDemo(){
  const now=new Date(),year=now.getFullYear(),month=now.getMonth()+1,key=`${year}-${String(month).padStart(2,'0')}`;
  const demo={version:1,demo:true,people:{kai:'凱',han:'涵'},categories:[...DEFAULT_CATEGORIES],expenses:[],incomes:[],settlements:{},config:{year,month,budget:4200,cloudUrl:''}};
  const rows=[
    [23,'一起吃的越南河粉','外食',28.5,'shared','kai',1.43,0,'週五的小約會'],[23,'青江菜','蔬菜',7.08,'shared','kai',0,0,'T&T'],[23,'花生醬','調味料',3.99,'shared','kai',0,0,'早餐的快樂'],[23,'冰拿鐵','咖啡',5.75,'han','han',0.29,0,''],[22,'洗衣精','日用品',12.97,'shared','kai',0.65,0.91,''],[21,'雞胸肉','肉類',14.5,'shared','han',0,0,'一週的便當'],[20,'小花束','個人消費',12,'han','kai',0.6,0.84,'給平凡日子一點可愛'],[19,'一週公車票','交通',28,'kai','kai',0,0,''],[18,'手工餅乾','零食',4.5,'shared','han',0,0,''],[17,'牛奶','牛奶',5.49,'shared','kai',0,0,''],[16,'週末早午餐','外食',42,'shared','han',2.1,0,''],[15,'家裡的網路費','住宅',65,'shared','kai',3.25,4.55,''],[14,'超市採買','蔬菜',38.6,'shared','han',0,0,'Walmart'],[13,'咖啡豆','咖啡',18,'shared','kai',0,0,''],[12,'兩顆可頌','米/麵/泡麵/麵包',8.5,'shared','han',0,0,''],[10,'洗髮精','日用品',16.99,'kai','kai',0.85,1.19,''],[8,'週末電影','個人消費',26,'shared','kai',1.3,0,''],[7,'雞蛋','雞蛋',6.49,'shared','han',0,0,''],[5,'一起煮火鍋','肉類',48.8,'shared','kai',0,0,''],[3,'藍莓','水果',5.99,'shared','han',0,0,''],[1,'這個月的房租','房租',1850,'shared','kai',0,0,'我們的小窩']
  ];
  rows.forEach((r,i)=>demo.expenses.push({id:i+1,date:`${key}-${String(Math.min(r[0],new Date(year,month,0).getDate())).padStart(2,'0')}`,name:r[1],cat:r[2],price:r[3],priceExpr:String(r[3]),qty:1,who:r[4],paidBy:r[5],gst:r[6],pst:r[7],note:r[8]}));
  demo.incomes=[{id:1,date:key+'-01',source:'本月薪水',amount:3800,who:'kai'},{id:2,date:key+'-01',source:'本月薪水',amount:3400,who:'han'}];
  for(let m=1;m<month;m++){
    const d=`${year}-${String(m).padStart(2,'0')}-01`,amount=round(2300+(m*83)%650);
    demo.expenses.push({id:100+m,date:d,name:'日常生活支出',cat:'住宅',price:amount,priceExpr:String(amount),qty:1,who:'shared',paidBy:m%2?'kai':'han',gst:0,pst:0,note:'年度回顧範例'});
    demo.incomes.push({id:100+m*2,date:d,source:'本月薪水',amount:3800,who:'kai'},{id:101+m*2,date:d,source:'本月薪水',amount:3400,who:'han'});
  }
  return demo;
}
let initialLoadError=false;
function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)return validateState(JSON.parse(raw));}catch{initialLoadError=true;}return makeDemo();}
let state=loadState();
const ui={page:PAGE_INFO[location.hash.slice(1)]?location.hash.slice(1):'overview',year:state.config.year,month:state.config.month,type:'expense',query:'',category:'',who:'',selection:new Set(),pageNum:1,entryKind:'expense',editingId:null,batchIds:[],day:null};
let toastTimer,confirmCallback=null,cloudBusy=false;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function commit(change,{renderPage=true}={}){
  const next=JSON.parse(JSON.stringify(state));change(next);next.config.year=ui.year;next.config.month=ui.month;
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));}catch{toast('儲存失敗，資料尚未更改。請檢查瀏覽器的儲存空間。');return false;}
  state=next;if(renderPage)render();return true;
}
function person(key){return state.people[key]||key;}
function avatar(key,extra=''){return `<span class="avatar ${key} ${extra}">${esc(person(key).slice(0,1))}</span>`;}
function categoryIcon(cat){const [glyph,bg]=CAT_META[cat]||['✳','#eee9f4'];return `<span class="category-icon" style="background:${bg}">${glyph}</span>`;}
function monthlyExpenses(){return state.expenses.filter(inMonth);}
function monthlyIncomes(){return state.incomes.filter(inMonth);}
function isTransfer(record){return !!record.settlementKey||['涵還款','凱還款'].includes(record.source);}
function personalTotals(records){let kaiSpend=0,hanSpend=0,kaiPaid=0,hanPaid=0;records.forEach(e=>{const n=total(e);if(e.who==='kai')kaiSpend+=n;else if(e.who==='han')hanSpend+=n;else{kaiSpend+=n/2;hanSpend+=n/2;}if(e.paidBy==='kai')kaiPaid+=n;else hanPaid+=n;});return {kaiSpend:round(kaiSpend),hanSpend:round(hanSpend),kaiPaid:round(kaiPaid),hanPaid:round(hanPaid)};}
function calcSettle(records){const p=personalTotals(records);return round(p.kaiSpend-p.kaiPaid);}
function settlementBalance(key=monthKey()){const raw=calcSettle(state.expenses.filter(e=>e.date.startsWith(key+'-')));const paid=state.settlements[key];return round(raw-(paid?(paid.from==='kai'?paid.amount:-paid.amount):0));}
function metric(label,value,symbol,foot,green=false){return `<div class="metric"><div class="metric-label"><span class="metric-symbol ${green?'green':''}">${symbol}</span>${label}</div><div class="metric-amount ${green?'green':''}">${money(value)}<small>CAD</small></div><div class="metric-foot">${foot}</div></div>`;}
function metrics(year=false){const prefix=String(ui.year),ex=state.expenses.filter(e=>year?e.date.startsWith(prefix+'-'):inMonth(e)),inc=state.incomes.filter(e=>(year?e.date.startsWith(prefix+'-'):inMonth(e))&&!isTransfer(e));const spend=sum(ex,total),income=sum(inc,e=>e.amount);let due=year?sum(Array.from({length:12},(_,i)=>`${ui.year}-${String(i+1).padStart(2,'0')}`),k=>Math.abs(settlementBalance(k))):Math.abs(settlementBalance());const balance=settlementBalance();return `<section class="metrics" aria-label="${year?'全年':'本月'}收支摘要">${metric(year?'全年支出':'本月支出',spend,'↗',`${ex.length} 筆被好好記下的日常`)}${metric(year?'全年收入':'本月收入',income,'↙',`${esc(person('kai'))}與${esc(person('han'))}，一起努力的成果`)}${metric(year?'全年結餘':'本月結餘',income-spend,'+',income>=spend?'多一點餘裕，留給喜歡的生活':'本期支出高於收入',income>=spend)}${metric('待分帳金額',due,'♡',year?'各月份尚未結清金額合計':Math.abs(balance)<0.01?'帳目平平，心情也平平穩穩':`${esc(person(balance>0?'kai':'han'))} → ${esc(person(balance>0?'han':'kai'))}`)}</section>`;}
function recentRows(records,limit=6){if(!records.length)return emptyView('還沒有小日常','記下第一筆，讓帳本慢慢有我們的樣子。');return `<div class="recent-list">${[...records].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id).slice(0,limit).map(e=>`<button class="recent-row" style="width:100%;text-align:left" data-action="edit-entry" data-id="${e.id}" data-kind="expense" aria-label="編輯${esc(e.name)}">${categoryIcon(e.cat)}<span class="recent-description"><strong>${esc(e.name)}</strong><small>${e.date.slice(5).replace('-','.')} · ${esc(e.cat)} · ${e.who==='shared'?'一起的':esc(person(e.who))+'的'}</small></span><span class="recent-amount"><strong>− ${money(total(e))}</strong><small>${esc(person(e.paidBy))}先付</small></span></button>`).join('')}</div>`;}
function categorySummary(records){const groups={};records.forEach(e=>groups[e.cat]=(groups[e.cat]||0)+total(e));const sorted=Object.entries(groups).sort((a,b)=>b[1]-a[1]);if(sorted.length<=5)return sorted;return [...sorted.slice(0,4),['其他',sum(sorted.slice(4),e=>e[1])]];}
function donutContent(records){const all=sum(records,total),groups=categorySummary(records);let offset=0;const circles=groups.map(([cat,n],i)=>{const length=all?n/all*301.59:0;const c=`<circle cx="60" cy="60" r="48" fill="none" stroke="${PALETTE[i]}" stroke-width="10" stroke-dasharray="${Math.max(0,length-3)} ${301.59-Math.max(0,length-3)}" stroke-dashoffset="${-offset}"/>`;offset+=length;return c;}).join('');return `<div class="donut-content"><div class="donut-wrap"><svg class="donut" viewBox="0 0 120 120" role="img" aria-label="支出分類圓環圖"><circle cx="60" cy="60" r="48" fill="none" stroke="#f3eef7" stroke-width="10"/>${circles}</svg><div class="donut-label"><span>本期花費</span><strong>${money(all)}</strong><small>CAD</small></div></div><div class="category-legend">${groups.length?groups.map(([cat,n],i)=>`<div class="legend-row"><i class="legend-dot" style="background:${PALETTE[i]}"></i><span>${esc(cat)}</span><strong>${money(n)}</strong><small>${all?Math.round(n/all*100):0}%</small></div>`).join(''):'<p class="muted">第一筆花費，會從這裡開始。</p>'}</div></div>`;}
function renderOverview(){const ex=monthlyExpenses(),due=settlementBalance(),budget=state.config.budget,spent=sum(ex,total);return `<section class="hero" aria-label="一個帳本，兩個人的日常"><div class="hero-copy"><span class="hero-pill">一個帳本，兩個人的日常</span><h2>一點一點，<br>把日子存起來<span class="little-star">✳</span></h2><p>不只記下花了多少，<br>也記得我們一起生活的模樣。</p></div><div class="cat-family" role="img" aria-label="五隻貓咪並排陪你記帳，會隨滑鼠自然轉頭"><span class="cat-portrait cat-1" data-cat="1" aria-hidden="true"><canvas class="cat-motion" width="512" height="768"></canvas></span><span class="cat-portrait cat-2" data-cat="2" aria-hidden="true"><canvas class="cat-motion" width="512" height="768"></canvas></span><span class="cat-portrait cat-3" data-cat="3" aria-hidden="true"><canvas class="cat-motion" width="512" height="768"></canvas></span><span class="cat-portrait cat-4" data-cat="4" aria-hidden="true"><canvas class="cat-motion" width="512" height="768"></canvas></span><span class="cat-portrait cat-5" data-cat="5" aria-hidden="true"><canvas class="cat-motion" width="512" height="768"></canvas></span></div><span class="hero-script">little by little, together.</span></section>${metrics()}<div class="dashboard-grid"><section class="panel"><header class="panel-head"><div><h2>最近的日常</h2><p>那些小小的、好好生活的證明</p></div><button class="text-button" data-page="records">全部明細 ${icon('arrow')}</button></header>${recentRows(ex)}</section><section class="panel"><header class="panel-head"><div><h2>這個月，花在哪裡？</h2><p>讓每一分錢，都有清楚的去向</p></div><span style="color:#c6b5d6;font-size:21px">✴</span></header><div class="panel-body">${donutContent(ex)}${budget>0?`<div class="budget-progress" role="progressbar" aria-label="本月預算使用比例" aria-valuenow="${Math.round(spent/budget*100)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,spent/budget*100)}%;${spent>budget?'background:#d2a3af':''}"></span></div><div class="budget-caption"><span>本月預算 CAD ${money(budget)}</span><span>${Math.round(spent/budget*100)}%</span></div>`:''}</div></section></div><div class="together-strip"><span class="small-heart">♡</span><p>${Math.abs(due)<.01?'<strong>這個月的帳目剛剛好。</strong> 謝謝一起好好生活的我們。':`<strong>${esc(person(due>0?'kai':'han'))}需要轉給${esc(person(due>0?'han':'kai'))} CAD ${money(Math.abs(due))}。</strong> 不用心算，兩個人的分帳在這裡。`}</p><button class="text-button" data-page="settlement">看分帳 ${icon('arrow')}</button></div>`;}
function emptyView(title,description,button=false){return `<div class="empty"><span class="empty-spark">✳</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${button?`<button class="button subtle" data-action="add">${icon('plus')}記下第一筆</button>`:''}</div>`;}
function getFiltered(){const kw=ui.query.trim().toLocaleLowerCase();return (ui.type==='expense'?state.expenses:state.incomes).filter(e=>inMonth(e)&&(!ui.category||e.cat===ui.category)&&(!ui.who||e.who===ui.who)&&(!kw||[e.date,e.name||e.source,e.cat,e.note].join(' ').toLocaleLowerCase().includes(kw))).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);}
function recordRow(e){const expense=ui.type==='expense';return `<tr class="${ui.selection.has(e.id)?'selected':''}" data-record-id="${e.id}"><td><input type="checkbox" id="record-checkbox-${e.id}" data-select-id="${e.id}" aria-label="選取${esc(e.name||e.source)}" ${ui.selection.has(e.id)?'checked':''}></td><td class="date-cell">${e.date.slice(5).replace('-','.')}<small style="display:block;color:#c7b6d1;font-size:8px">${e.date.slice(0,4)}</small></td><td class="record-name"><strong>${esc(e.name||e.source)}</strong>${e.note?`<small>${esc(e.note)}</small>`:''}${isTransfer(e)?'<small>分帳還款紀錄</small>':''}</td>${expense?`<td><span class="category-chip">${esc(e.cat)}</span></td>`:''}<td><span class="who-badge">${e.who==='shared'?'<span class="avatar micro" style="background:#f0eaf6;color:#ae99bd">♡</span>一起的':avatar(e.who,'micro')+esc(person(e.who))}</span></td>${expense?`<td>${avatar(e.paidBy,'micro')}</td><td class="amount-cell">${money(e.price*e.qty)}${e.qty!==1?`<small>${e.qty} × ${money(e.price)}</small>`:''}</td><td class="amount-cell" style="color:#bca7c8;font-size:10px">${e.gst?money(e.gst):'—'}<small>${e.pst?'PST '+money(e.pst):''}</small></td>`:''}<td class="amount-cell">${expense?'−':'+'} ${money(expense?total(e):e.amount)}</td><td><div class="row-actions"><button class="icon-button" data-action="edit-entry" data-kind="${ui.type}" data-id="${e.id}" aria-label="編輯${esc(e.name||e.source)}">${icon('edit')}</button><button class="icon-button" data-action="delete-entry" data-kind="${ui.type}" data-id="${e.id}" aria-label="刪除${esc(e.name||e.source)}">${icon('trash')}</button></div></td></tr>`;}
function renderRecords(){const rows=getFiltered(),pageSize=20,pages=Math.max(1,Math.ceil(rows.length/pageSize));ui.pageNum=Math.min(ui.pageNum,pages);const validIds=new Set(rows.map(e=>e.id));for(const id of ui.selection)if(!validIds.has(id))ui.selection.delete(id);const amount=sum(rows,e=>ui.type==='expense'?total(e):e.amount);return `<section class="panel"><header class="panel-head"><div><h2>${ui.month}月的日常明細</h2><p>先搜尋日期，再全選，一整批也能輕鬆更正</p></div><div class="segmented" aria-label="明細種類"><button class="${ui.type==='expense'?'active':''}" data-action="record-type" data-kind="expense">支出</button><button class="${ui.type==='income'?'active':''}" data-action="record-type" data-kind="income">收入</button></div></header><div class="filters"><label class="search-box">${icon('search')}<input id="record-search" placeholder="搜尋品項、備註或日期…" aria-label="搜尋品項、備註或日期" value="${esc(ui.query)}" autocomplete="off"></label>${ui.type==='expense'?`<select class="filter-select" id="category-filter" aria-label="篩選分類"><option value="">全部分類</option>${state.categories.map(c=>`<option ${ui.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:''}<select class="filter-select" id="who-filter" aria-label="篩選歸屬"><option value="">全部歸屬</option>${['kai','han',...(ui.type==='expense'?['shared']:[])].map(w=>`<option value="${w}" ${ui.who===w?'selected':''}>${w==='shared'?'一起的':esc(person(w))+'的'}</option>`).join('')}</select><button class="icon-button" data-action="clear-filters" aria-label="清除篩選">${icon('close')}</button></div>${ui.selection.size?`<div class="selection-bar"><span>已選取 <b>${ui.selection.size}</b> 筆</span><button class="button white small" data-action="batch-date">${icon('calendar')}批次改日期</button><button class="text-button" data-action="clear-selection">取消勾選</button></div>`:`<div class="filter-count"><span>共 ${rows.length} 筆 · 合計 CAD ${money(amount)}</span><span>勾選明細，可以一次更改日期</span></div>`}<div class="table-scroll"><table class="records-table"><thead><tr><th><input type="checkbox" id="select-all-records" aria-label="全選全部搜尋結果，共${rows.length}筆" ${rows.length&&ui.selection.size===rows.length?'checked':''} ${rows.length?'':'disabled'}></th><th>日期</th><th>${ui.type==='expense'?'項目':'收入來源'}</th>${ui.type==='expense'?'<th>分類</th>':''}<th>歸屬</th>${ui.type==='expense'?'<th>先付款</th><th style="text-align:right">金額</th><th style="text-align:right">GST / PST</th>':''}<th style="text-align:right">${ui.type==='expense'?'含稅合計':'收入金額'} · CAD</th><th></th></tr></thead><tbody>${rows.slice((ui.pageNum-1)*pageSize,ui.pageNum*pageSize).map(recordRow).join('')}</tbody></table></div>${rows.length?'':emptyView(ui.query||ui.category||ui.who?'沒有找到這樣的日常':'這個月還是空白的',ui.query||ui.category||ui.who?'試著換個關鍵字，或清除篩選。':'記下第一筆，讓日子慢慢有自己的模樣。',!(ui.query||ui.category||ui.who))}<footer class="pagination"><span>${rows.length?`${(ui.pageNum-1)*pageSize+1}–${Math.min(ui.pageNum*pageSize,rows.length)} / ${rows.length} 筆`:'0 筆'} · 全選會選取全部搜尋結果</span><div><button class="icon-button" data-action="prev-page" aria-label="上一頁" ${ui.pageNum===1?'disabled':''}>${icon('chevron','flipped')}</button><span style="align-self:center">${ui.pageNum} / ${pages}</span><button class="icon-button" data-action="next-page" aria-label="下一頁" ${ui.pageNum===pages?'disabled':''}>${icon('chevron')}</button></div></footer></section>`;}
function renderCalendar(){const first=(new Date(ui.year,ui.month-1,1).getDay()+6)%7,days=new Date(ui.year,ui.month,0).getDate(),today=localDate(),byDay={};monthlyExpenses().forEach(e=>(byDay[e.date]??=[]).push(e));let cells=Array.from({length:first},()=>'<div class="calendar-day blank" aria-hidden="true"></div>').join('');for(let day=1;day<=days;day++){const date=monthKey()+'-'+String(day).padStart(2,'0'),records=byDay[date]||[];cells+=`<button class="calendar-day ${date===today?'today':''} ${records.length?'has-data':''}" data-action="open-day" data-date="${date}" aria-label="${ui.month}月${day}日，${records.length}筆支出${records.length?'，CAD '+money(sum(records,total)):''}"><span class="day-number">${day}</span>${records.slice(0,2).map(e=>`<span class="day-preview">${esc(e.name)}</span>`).join('')}<span class="day-total">${records.length?money(sum(records,total)):''}</span></button>`;}return `${metrics()}<section class="panel calendar-panel"><header class="calendar-head"><div><h2>${ui.year}年 ${ui.month}月</h2><p style="text-align:left;margin-top:7px;max-width:none">每一天，都有好好生活的痕跡</p></div><p>點選日期，查看明細<br>也可以直接新增一筆</p></header><div class="calendar-week">${['一','二','三','四','五','六','日'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells}</div></section>`;}
function renderSettlement(){const ex=monthlyExpenses(),p=personalTotals(ex),due=settlementBalance(),raw=calcSettle(ex),paid=state.settlements[monthKey()],shared=sum(ex.filter(e=>e.who==='shared'),total),finance=LedgerModel.summary(state,ui.year,String(ui.month).padStart(2,'0'));return `<section class="settle-hero"><div><p class="eyebrow">OUR FAIR SHARE</p><h2>${Math.abs(due)<.01?'帳目剛剛好，一起鬆口氣。':`${esc(person(due>0?'kai':'han'))}轉給${esc(person(due>0?'han':'kai'))}，就平了。`}</h2><p>共同花費各分一半，個人消費自己負擔。<br>不必心算，把清楚留給帳本，把溫柔留給彼此。</p></div><div class="settle-amount">${money(Math.abs(due))} <small>CAD</small></div>${Math.abs(due)>=.01?`<button class="button white" data-action="mark-paid">${icon('check')}已完成轉帳</button>`:'<span class="category-chip">♡ 本月已結清</span>'}</section><div class="people-grid">${['kai','han'].map(w=>`<section class="panel"><div class="panel-body" style="padding-top:26px"><div class="person-head">${avatar(w,'large')}<div><h3>${esc(person(w))}的這個月</h3><small>一筆一筆，都算清楚了</small></div></div><div class="person-stats"><div><span>實際先付</span><strong>${money(p[w+'Paid'])}</strong></div><div><span>應負擔花費</span><strong>${money(p[w+'Spend'])}</strong></div></div><div style="margin-top:20px"><div class="stat-detail"><span>自己的花費</span><strong>CAD ${money(sum(ex.filter(e=>e.who===w),total))}</strong></div><div class="stat-detail"><span>共同花費的一半</span><strong>CAD ${money(shared/2)}</strong></div><div class="stat-detail"><span>先付 − 應負擔</span><strong>${p[w+'Paid']>=p[w+'Spend']?'+':'−'} CAD ${money(Math.abs(p[w+'Paid']-p[w+'Spend']))}</strong></div><div class="stat-detail"><span>本月收入</span><strong>CAD ${money(finance.income[w])}</strong></div><div class="stat-detail"><span>本月結餘</span><strong>CAD ${money(finance.balance[w])}</strong></div>${w==='kai'&&finance.extra?`<div class="stat-detail"><span>個人消費另扣</span><strong>CAD ${money(finance.extra)}</strong></div>`:''}<div class="stat-detail"><span>累計資產</span><strong>CAD ${money(finance.cumulative[w])}</strong></div></div></div></section>`).join('')}</div><section class="panel" style="margin-top:22px"><header class="panel-head"><div><h2>這個月的分帳紀錄</h2><p>實際轉帳後再標記；這裡只記錄，不會替你轉帳</p></div></header><div class="panel-body"><div class="stat-detail"><span>本月結算標記</span><button class="button subtle small" data-action="month-settled">${ledgerRaw['hh_settled_'+String(ui.month).padStart(2,'0')]==='1'?'✓ 已結算・取消標記':'標記已結算'}</button></div><div class="stat-detail"><span>原始應分帳</span><strong>${Math.abs(raw)<.01?'無需互轉':esc(person(raw>0?'kai':'han'))+' → '+esc(person(raw>0?'han':'kai'))+' CAD '+money(Math.abs(raw))}</strong></div>${paid?`<div class="stat-detail"><span>${esc(paid.date)} 已記錄轉帳<br><small>${esc(person(paid.from))} → ${esc(person(paid.to))} CAD ${money(paid.amount)}</small></span><button class="text-button" data-action="undo-paid">取消還款紀錄</button></div>`:'<p class="muted" style="padding:14px 0">還沒有轉帳紀錄，慢慢來，等實際轉帳後再記下。</p>'}</div></section>`;}
function renderYear(){const months=Array.from({length:12},(_,i)=>{const key=`${ui.year}-${String(i+1).padStart(2,'0')}`,ex=state.expenses.filter(e=>e.date.startsWith(key+'-')),inc=state.incomes.filter(e=>e.date.startsWith(key+'-'));return {month:i+1,expense:sum(ex,total),income:sum(inc,e=>e.amount),count:ex.length};}),max=Math.max(...months.flatMap(m=>[m.expense,m.income]),1);const balances=months.map(m=>{const s=LedgerModel.summary(state,ui.year,String(m.month).padStart(2,'0'));return [s.cumulative.kai,s.cumulative.han];});const maxBalance=Math.max(...balances.flat().map(Math.abs),1),positive=balances.every(b=>b.every(v=>v>=0));const point=(v,i)=>`${43+i*58},${positive?170-v/maxBalance*140:100-v/maxBalance*75}`;return `${metrics(true)}<section class="panel"><header class="panel-head"><div><h2>這一年的收入與花費</h2><p>把日常拉遠一點，看看我們一起走過的路</p></div><div class="chart-key"><span><i style="background:#c8d5be"></i>收入</span><span><i style="background:#bfacd7"></i>支出</span></div></header><div class="panel-body"><svg class="year-chart" viewBox="0 0 740 210" role="img" aria-label="${ui.year}年各月份收入與支出長條圖">${[0,1,2,3].map(i=>`<path d="M25 ${25+i*48}H730" stroke="#f0ebf5"/>`).join('')}${months.map((m,i)=>{const x=35+i*58;return `<g><title>${m.month}月：收入 CAD ${money(m.income)}，支出 CAD ${money(m.expense)}</title><rect x="${x}" y="${170-m.income/max*140}" width="15" height="${m.income/max*140}" rx="4" fill="#c8d5be"/><rect x="${x+19}" y="${170-m.expense/max*140}" width="15" height="${m.expense/max*140}" rx="4" fill="#bfacd7"/><text x="${x+16}" y="195" text-anchor="middle" fill="#b8a6c6" font-size="9">${m.month}月</text></g>`;}).join('')}</svg></div></section><div class="dashboard-grid" style="margin-top:22px"><section class="panel"><header class="panel-head"><div><h2>慢慢累積的餘裕</h2><p>依帳本計算的兩人累計資產</p></div><div class="chart-key"><span><i style="background:#aabbd1"></i>${esc(person('kai'))}</span><span><i style="background:#d9b0c2"></i>${esc(person('han'))}</span></div></header><div class="panel-body"><svg class="year-chart" viewBox="0 0 740 205" role="img" aria-label="兩人各月份累計結餘趨勢"><path d="M25 ${positive?170:100}H730" stroke="#eee7f4"/>${[0,1].map((w)=>`<polyline points="${balances.map((b,i)=>point(b[w],i)).join(' ')}" fill="none" stroke="${w?'#d9b0c2':'#aabbd1'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${balances.map((b,i)=>`<circle cx="${43+i*58}" cy="${point(b[w],i).split(',')[1]}" r="3.5" fill="${w?'#d9b0c2':'#aabbd1'}"><title>${i+1}月 ${esc(person(w?'han':'kai'))}累計 CAD ${money(b[w])}</title></circle>`).join('')}`).join('')}${months.map((m,i)=>`<text x="${43+i*58}" y="195" text-anchor="middle" fill="#b8a6c6" font-size="9">${m.month}月</text>`).join('')}</svg></div></section><section class="panel"><header class="panel-head"><h2>全年花費的樣子</h2></header><div class="panel-body">${donutContent(state.expenses.filter(e=>e.date.startsWith(ui.year+'-')))}</div></section></div><div class="year-grid">${months.map(m=>`<button class="year-month ${m.month===ui.month?'active':''}" data-action="jump-month" data-month="${m.month}"><h3>${String(m.month).padStart(2,'0')} / ${ui.year}</h3><strong>${money(m.expense)}</strong><small>${m.count} 筆日常 <span style="float:right">↗</span></small></button>`).join('')}</div>`;}
function renderSettings(){return `<div class="settings-grid"><div><section class="panel settings-section"><header class="panel-head"><div><h2>讓帳本像我們</h2><p>名稱與每月預算，隨生活慢慢調整</p></div></header><form id="preferences-form" class="panel-body"><div class="form-grid"><label class="field"><span>第一位成員</span><input name="kai" value="${esc(person('kai'))}" maxlength="10" required></label><label class="field"><span>第二位成員</span><input name="han" value="${esc(person('han'))}" maxlength="10" required></label></div><label class="field"><span>每月預算 · CAD（填 0 可不設定）</span><input name="budget" type="number" min="0" step="0.01" value="${state.config.budget}"></label><button class="button subtle small" type="submit" style="margin-top:16px">儲存此裝置的顯示設定</button></form></section><section class="panel settings-section"><header class="panel-head"><div><h2>資料與備份</h2><p>重要的日常，記得留一份在自己手上</p></div></header><div class="panel-body"><div class="setting-row"><div><p>匯出完整備份</p><small>所有年度、原始金額、算式、備註與還款標記。</small></div><button class="button subtle" data-action="export-json">${icon('down')}匯出 JSON</button></div><div class="setting-row"><div><p>匯入帳本</p><small>支援原版家庭帳本完整備份；匯入前先自動備份。</small></div><button class="button subtle" data-action="import-json">匯入備份</button></div><div class="setting-row"><div><p>試算表也能打開</p><small>匯出 ${ui.year} 年全部收支，或目前月份的明細。</small></div><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="button subtle small" data-action="export-csv">本月 CSV</button><button class="button subtle small" data-action="export-year">全年 CSV</button></div></div><div class="setting-row"><div><p>需要回到上一份帳目？</p><small>下載或還原最近一次自動備份。</small></div><div class="backup-actions"><button class="text-button" data-action="download-safety">下載備份</button><button class="text-button" data-action="restore-safety">還原備份</button></div></div></div></section><section class="panel settings-section"><header class="panel-head"><div><h2>手機、電腦，同一本日常</h2><p>記好後同步，到哪裡都能查看</p></div></header><div class="panel-body"><p class="helper" style="margin:0 0 18px">電腦修改後按「雲端同步」，手機開啟相同網址即可載入。若兩台裝置的資料不同，會保留本機並提示，避免互相覆蓋。</p><form id="cloud-form" class="cloud-form"><label class="field"><span>Google Apps Script 同步服務網址</span><input name="cloudUrl" type="url" value="${esc(state.config.cloudUrl)}" autocomplete="off"></label><button class="button subtle small" type="submit">儲存網址</button></form><div class="cloud-buttons" style="margin-top:18px"><button class="button subtle" data-action="cloud-upload" ${cloudBusy?'disabled':''}>${icon('cloud')}雲端同步</button><button class="button subtle" data-action="cloud-load" ${cloudBusy?'disabled':''}>從雲端載入</button></div></div></section><section class="panel settings-section"><header class="panel-head"><h2>日常的分類</h2><button class="text-button" data-action="new-category">＋ 新增分類</button></header><div class="panel-body category-settings">${state.categories.map(c=>`<span>${esc(c)}</span>`).join('')}</div></section></div><aside><section class="settings-note"><span>♡</span><h3>每一個日常，都好好留著。</h3><p>完整帳目保存在裝置與你設定的雲端服務。更換裝置前，記得按一下雲端同步。</p><p style="margin-top:14px">每次匯入或載入雲端前，也會替目前的帳目留一份本機備份。</p></section><section class="panel" style="margin-top:22px"><header class="panel-head"><div><h2>採買小幫手</h2><p>常買的東西，出門前再看一眼</p></div></header><div class="panel-body"><button class="button subtle" onclick="openDealModal()">查看本週常買商品特價 ↗</button><a class="text-button" href="https://yenthesoloman.github.io/grocery/" target="_blank" rel="noopener noreferrer" style="margin-top:15px">打開採買比價工具 ↗</a></div></section></aside></div>`;}
function render(){
  const active=document.activeElement,focusId=active?.id,caret=active?.selectionStart,info=PAGE_INFO[ui.page];
  $('#page-title').textContent=info[1];$('#page-eyebrow').textContent=info[0];$('#page-description').textContent=info[2];$('#breadcrumb-current').textContent=info[3];
  document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===ui.page);if(b.dataset.page===ui.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  const years=[...new Set([ui.year,new Date().getFullYear(),...state.expenses.map(e=>Number(e.date.slice(0,4))),...state.incomes.map(e=>Number(e.date.slice(0,4))),ui.year-1,ui.year+1])].sort((a,b)=>a-b);
  $('#period-month').innerHTML=Array.from({length:12},(_,i)=>`<option value="${i+1}" ${i+1===ui.month?'selected':''}>${i+1}月</option>`).join('');$('#period-year').innerHTML=years.map(y=>`<option ${y===ui.year?'selected':''}>${y}</option>`).join('');$('#period-month').hidden=ui.page==='year';$('#demo-banner').hidden=true;
  $('#page-content').innerHTML=({overview:renderOverview,records:renderRecords,calendar:renderCalendar,settlement:renderSettlement,year:renderYear,settings:renderSettings})[ui.page]();
  const selectAll=$('#select-all-records');if(selectAll)selectAll.indeterminate=ui.selection.size>0&&ui.selection.size<getFiltered().length;
  $('.workspace-label').innerHTML=`<span class="tiny-dot"></span> ${esc(person('kai'))} & ${esc(person('han'))}的生活帳本 <span class="workspace-heart">♡</span>`;
  $('.couple-avatars').innerHTML=avatar('kai')+avatar('han');
  if(focusId&&document.getElementById(focusId)){const next=document.getElementById(focusId);next.focus({preventScroll:true});if(typeof caret==='number'&&next.setSelectionRange)try{next.setSelectionRange(caret,caret);}catch{}}
  document.dispatchEvent(new Event('ledger:render'));
}
function resetFilters(){ui.query='';ui.category='';ui.who='';ui.selection.clear();ui.pageNum=1;}
function goPage(page){if(!PAGE_INFO[page])return;if($('#nav-dialog').open)$('#nav-dialog').close();ui.page=page;resetFilters();history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'instant'});}
function changePeriod(year,month){if(year<1900||year>2199)return;ui.year=year;ui.month=month;resetFilters();commit(()=>{});}
function shiftMonth(delta){const date=new Date(ui.year,ui.month-1+delta,1);changePeriod(date.getFullYear(),date.getMonth()+1);}
function showDialog(id){const dialog=document.getElementById(id);if(!dialog.open)dialog.showModal();}
function openEntry(kind='expense',id=null,date=null){
  ui.entryKind=kind;ui.editingId=id;const form=$('#entry-form');form.reset();$('#entry-error').textContent='';const record=id!==null?(kind==='expense'?state.expenses:state.incomes).find(e=>e.id===id):null;
  if(id!==null&&!record)return;
  $('#entry-title').textContent=record?'把這一筆改好':'記下這一筆';$('#entry-submit').innerHTML=record?'儲存修改 ↗':'存好這一筆 ↗';
  $('#entry-category').innerHTML=state.categories.map(c=>`<option>${esc(c)}</option>`).join('');
  const fallback=localDate().startsWith(monthKey())?localDate():monthKey()+'-01';form.elements.date.value=date||record?.date||fallback;
  if(record){form.elements.name.value=record.name||record.source;form.elements.priceExpr.value=kind==='expense'?(record.priceExpr||String(record.price)):String(record.amount);if(kind==='expense'){form.elements.qty.value=record.qty;form.elements.cat.value=record.cat;form.elements.who.value=record.who;form.elements.paidBy.value=record.paidBy;form.elements.gst.value=record.gst||'';form.elements.pst.value=record.pst||'';form.elements.note.value=record.note||'';}else form.elements.incomeWho.value=record.who;}
  document.querySelectorAll('[data-person]').forEach(el=>{const group=el.closest('.choice-row')?.parentElement;el.textContent=person(el.dataset.person)+(group?.id==='who-choices'?'的':'');});
  setEntryKind(kind);showDialog('entry-dialog');
  $('#entry-price').focus();
}
function setEntryKind(kind){if(ui.editingId!==null&&kind!==ui.entryKind)return;ui.entryKind=kind;$('#expense-fields').hidden=kind!=='expense';$('#income-fields').hidden=kind!=='income';document.querySelectorAll('[data-kind]').forEach(b=>{if(b.closest('.entry-kind')){b.classList.toggle('active',b.dataset.kind===kind);b.disabled=ui.editingId!==null&&b.dataset.kind!==kind;}});$('#entry-name-label').textContent=kind==='expense'?'買了什麼？':'收入來源';$('#entry-name').placeholder=kind==='expense'?'例如：一起吃的晚餐':'例如：本月薪水';$('#entry-qty').required=kind==='expense';updateFormula();}
function updateFormula(){const form=$('#entry-form'),price=parseAmount(form.elements.priceExpr.value),qty=Number(form.elements.qty.value)||0,gst=parseAmount(form.elements.gst.value)||0,pst=parseAmount(form.elements.pst.value)||0;$('#formula-result').textContent=price===null?(form.elements.priceExpr.value?'這個算式還沒算出來，檢查一下符號。':'可直接輸入算式，例如 32.30 / 2'):`算好了，CAD ${money(price)}${ui.entryKind==='expense'?' / 單件':''}`;$('#entry-total').textContent='CAD '+money(ui.entryKind==='expense'?(price||0)*qty+gst+pst:price||0);}
function nextId(records){return records.reduce((max,r)=>Math.max(max,Number(r.id)||0),0)+1;}
function saveEntry(event){event.preventDefault();const form=$('#entry-form'),values=new FormData(form),date=String(values.get('date')),name=String(values.get('name')).trim(),price=parseAmount(values.get('priceExpr')),expense=ui.entryKind==='expense',qty=Number(values.get('qty')),taxes=['gst','pst'].map(k=>String(values.get(k)).trim()?parseAmount(values.get(k)):0),error=$('#entry-error');
  if(!validDate(date)||!name||price===null||price<=0){error.textContent='日期、項目和大於 0 的有效金額，都要填好喔。';return;}
  if(expense&&(!Number.isFinite(qty)||qty<=0||qty>100000||taxes.some(n=>n===null||n<0))){error.textContent='請檢查數量與稅額。數量需要大於 0，稅額不能是負數。';return;}
  if(!expense&&ui.editingId!==null&&state.incomes.find(i=>i.id===ui.editingId)?.settlementKey){error.textContent='這筆是分帳還款紀錄，請從「兩人分帳」取消後重新記錄。';return;}
  const collection=expense?'expenses':'incomes',existing=state[collection].find(e=>e.id===ui.editingId),id=existing?.id||nextId(state[collection]);let record=expense?{...existing,id,date,name,price,priceExpr:String(values.get('priceExpr')).trim(),qty,cat:String(values.get('cat')),who:String(values.get('who')),paidBy:String(values.get('paidBy')),gst:taxes[0],pst:taxes[1],note:String(values.get('note')).trim()}:{...existing,id,date,source:name,amount:round(price),who:String(values.get('incomeWho'))};
  const oldYear=ui.year,oldMonth=ui.month;ui.year=Number(date.slice(0,4));ui.month=Number(date.slice(5,7));
  if(commit(s=>{const idx=s[collection].findIndex(e=>e.id===id);if(idx>=0)s[collection][idx]=record;else s[collection].push(record);},{renderPage:false})){$('#entry-dialog').close();resetFilters();render();toast(existing?'這一筆，已經改好了。':'又一筆日常，好好收進帳本了。');}else{ui.year=oldYear;ui.month=oldMonth;error.textContent='儲存失敗，請檢查瀏覽器儲存空間後重試。';}}
function openConfirm(title,copy,callback,label='確認'){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-submit').textContent=label;confirmCallback=callback;showDialog('confirm-dialog');}
function deleteEntry(kind,id){const collection=kind==='expense'?'expenses':'incomes',record=state[collection].find(e=>e.id===id);if(!record)return;if(record.settlementKey){toast('這筆是還款紀錄，請從「兩人分帳」取消。');return;}openConfirm('讓這一筆離開帳本？',`${record.date} · ${record.name||record.source}\nCAD ${money(kind==='expense'?total(record):record.amount)}\n確認後會刪除這一筆，本機會先自動備份。`,()=>{if(commit(s=>{s[collection]=s[collection].filter(e=>e.id!==id);})) {ui.selection.delete(id);toast('這一筆已刪除。');}},'確認刪除');}
function openBatch(){const records=getFiltered().filter(e=>ui.selection.has(e.id));if(!records.length)return;ui.batchIds=records.map(e=>({id:e.id,date:e.date}));ui.batchType=ui.type;$('#batch-summary').textContent=`已選取 ${records.length} 筆${ui.type==='expense'?'支出':'收入'}。一起把打錯的日期改好。`;const dates=[...new Set(records.map(e=>e.date))];$('#batch-date').value=dates.length===1?dates[0]:'';$('#batch-error').textContent='';showDialog('batch-dialog');}
function saveBatch(event){event.preventDefault();const date=$('#batch-date').value,collection=ui.batchType==='expense'?'expenses':'incomes',records=state[collection],error=$('#batch-error');if(!validDate(date)){error.textContent='請選擇 1900 至 2199 年之間的有效日期。';return;}if(ui.batchIds.some(old=>!records.some(e=>e.id===old.id&&e.date===old.date))){error.textContent='選取的資料已變更，請重新選取。';return;}if(ui.batchIds.some(old=>records.find(e=>e.id===old.id)?.settlementKey)){error.textContent='還款紀錄請從「兩人分帳」修改，避免分帳日期錯置。';return;}const ids=new Set(ui.batchIds.map(e=>e.id)),n=ids.size;if(commit(s=>{s[collection]=s[collection].map(e=>ids.has(e.id)?{...e,date}:e);},{renderPage:false})){$('#batch-dialog').close();ui.selection.clear();render();toast(`${n} 筆日期已統一改為 ${date}。${!date.startsWith(monthKey())?'已移至對應月份。':''}`);}else error.textContent='儲存失敗，日期尚未更動。';}
function openDay(date){ui.day=date;const ex=state.expenses.filter(e=>e.date===date),inc=state.incomes.filter(e=>e.date===date);$('#day-title').textContent=Number(date.slice(5,7))+'月'+Number(date.slice(8))+'日的小日常';$('#day-content').innerHTML=[...ex.map(e=>({...e,kind:'expense'})),...inc.map(e=>({...e,kind:'income'}))].map(e=>`<div class="day-item">${e.kind==='expense'?categoryIcon(e.cat):'<span class="category-icon">↙</span>'}<div><p>${esc(e.name||e.source)}</p><small>${e.kind==='expense'?esc(e.cat):'收入'} · ${e.who==='shared'?'一起的':esc(person(e.who))}</small></div><strong>${e.kind==='expense'?'−':'+'} ${money(e.kind==='expense'?total(e):e.amount)}</strong><button class="icon-button" data-action="day-edit" data-kind="${e.kind}" data-id="${e.id}" aria-label="編輯${esc(e.name||e.source)}">${icon('edit')}</button></div>`).join('')||emptyView('留一點空白，也很好','想記下什麼，就從這裡開始。');$('#day-content').insertAdjacentHTML('beforeend',`<button class="button subtle" data-action="day-add" style="width:100%;margin-top:20px">${icon('plus')}在這天新增一筆</button>`);showDialog('day-dialog');}
function markPaid(){const due=settlementBalance(),existing=state.settlements[monthKey()];if(Math.abs(due)<.01)return;if(existing){toast('這個月已經有還款紀錄，請先取消舊紀錄，再依目前金額記錄。');return;}const from=due>0?'kai':'han',to=due>0?'han':'kai',amount=Math.abs(due),key=monthKey();openConfirm('這筆轉帳，已經完成了嗎？',`${person(from)} → ${person(to)}\nCAD ${money(amount)}\n這裡只記錄實際還款，不會替你轉帳。`,()=>{if(commit(s=>{const incomeId=nextId(s.incomes),date=localDate().startsWith(key)?localDate():key+'-'+String(new Date(ui.year,ui.month,0).getDate()).padStart(2,'0');s.settlements[key]={amount,from,to,date,incomeId};s.incomes.push({id:incomeId,date,source:person(from)+'還款',who:to,amount,settlementKey:key});}))toast('還款已記錄，兩個人的帳又更清楚了。');},'已轉帳，記下還款');}
function undoPaid(){const key=monthKey();openConfirm('取消這個月的還款紀錄？','會移除這筆自動產生的還款收入，並重新計算待分帳金額。',()=>{if(commit(s=>{const id=s.settlements[key]?.incomeId;if(id)s.incomes=s.incomes.filter(i=>i.id!==id);delete s.settlements[key];}))toast('已取消還款紀錄。');},'確認取消');}
function newCategory(){const name=prompt('新的日常分類，叫什麼名字？');if(!name)return;const cat=name.trim().slice(0,30);if(!cat)return;if(state.categories.includes(cat)){toast('這個分類已經在帳本裡囉。');return;}if(commit(s=>s.categories.push(cat))){if($('#entry-dialog').open){const select=$('#entry-category');select.add(new Option(cat,cat));select.value=cat;}toast('新分類「'+cat+'」已收好。');}}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJSON(){const copy=JSON.parse(JSON.stringify(state));copy.config.cloudUrl='';download(JSON.stringify({format:'little-ledger',exportedAt:new Date().toISOString(),data:copy},null,2),`一起存_完整備份_${localDate()}.json`,'application/json;charset=utf-8');toast('備份已匯出，替小日子多留一份安心。');}
function csvCell(value){let str=String(value??'');if(/^[=+@\t\r]/.test(str)||/^-[^\d]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"';}
function exportCSV(year=false){const filter=e=>year?e.date.startsWith(ui.year+'-'):inMonth(e),rows=[['種類','日期','項目','分類','歸屬','付款人','數量','單價','GST','PST','合計','備註']];state.expenses.filter(filter).sort((a,b)=>a.date.localeCompare(b.date)).forEach(e=>rows.push(['支出',e.date,e.name,e.cat,e.who==='shared'?'共同':person(e.who),person(e.paidBy),e.qty,e.price,e.gst||0,e.pst||0,total(e),e.note||'']));state.incomes.filter(filter).sort((a,b)=>a.date.localeCompare(b.date)).forEach(e=>rows.push([isTransfer(e)?'還款':'收入',e.date,e.source,'',person(e.who),'','','','','',e.amount,'']));download('\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),`一起存_${year?ui.year:monthKey()}.csv`,'text/csv;charset=utf-8');toast('明細已匯出，可以用 Excel 開啟。');}
function validateRecord(record,expense,id){
  if(!record||!validDate(record.date))throw Error('備份包含無效日期。');const who=['kai','han',...(expense?['shared']:[])].includes(record.who)?record.who:null;if(!who)throw Error('備份包含無效的歸屬。');
  if(expense){if(!Number.isFinite(Number(record.qty))||Number(record.qty)<=0||!Number.isFinite(Number(record.price))||Number(record.price)<0||!['kai','han'].includes(record.paidBy))throw Error('備份包含無效的支出金額或付款人。');if([record.gst||0,record.pst||0].some(n=>!Number.isFinite(Number(n))||Number(n)<0))throw Error('備份包含無效稅額。');return {id,date:record.date,name:String(record.name||'未命名支出').slice(0,200),cat:String(record.cat||'其他').slice(0,30),qty:Number(record.qty),price:Number(record.price),priceExpr:String(record.priceExpr||record.price),who,paidBy:record.paidBy,gst:Number(record.gst)||0,pst:Number(record.pst)||0,note:String(record.note||'').slice(0,500)};}
  if(!Number.isFinite(Number(record.amount))||Number(record.amount)<0)throw Error('備份包含無效的收入金額。');return {...(record.settlementKey?{settlementKey:String(record.settlementKey)}:{}),id,date:record.date,source:String(record.source||'未命名收入').slice(0,200),who,amount:round(Number(record.amount))};
}
function validateState(input){
  if(!input||input.version!==1||!Array.isArray(input.expenses)||!Array.isArray(input.incomes)||input.expenses.length+input.incomes.length>100000)throw Error('這份檔案不是支援的帳本備份。');
  const demo=makeDemo(),incomeMap=new Map(),expenses=input.expenses.map((e,i)=>validateRecord(e,true,i+1)),incomes=input.incomes.map((e,i)=>{incomeMap.set(e.id,i+1);return validateRecord(e,false,i+1);}),settlements={};
  for(const [key,entry]of Object.entries(input.settlements||{})){if(!/^\d{4}-\d{2}$/.test(key)||!['kai','han'].includes(entry.from)||!['kai','han'].includes(entry.to)||entry.from===entry.to||!Number.isFinite(entry.amount)||entry.amount<0||!validDate(entry.date))continue;const incomeId=incomeMap.get(entry.incomeId);if(incomeId)settlements[key]={...entry,incomeId};}
  const year=Number(input.config?.year),month=Number(input.config?.month),budget=Number(input.config?.budget),cloudUrl=String(input.config?.cloudUrl||'');
  return {version:1,demo:input.demo===true,people:{kai:String(input.people?.kai||'凱').slice(0,10),han:String(input.people?.han||'涵').slice(0,10)},expenses,incomes,categories:[...new Set([...DEFAULT_CATEGORIES,...(Array.isArray(input.categories)?input.categories.map(c=>String(c).slice(0,30)):[]),...expenses.map(e=>e.cat)])],settlements,config:{year:Number.isInteger(year)&&year>=1900&&year<=2199?year:demo.config.year,month:Number.isInteger(month)&&month>=1&&month<=12?month:demo.config.month,budget:Number.isFinite(budget)&&budget>=0?budget:0,cloudUrl:cloudUrl.startsWith('https://')?cloudUrl:''}};
}
function parseBackup(input){
  if(input?.format==='little-ledger')return validateState(input.data);if(input?.version===1&&input.expenses)return validateState(input);
  const raw=input?.data&&typeof input.data==='object'?input.data:input;if(!raw||typeof raw!=='object')throw Error('備份格式不正確。');const data={...raw};
  Object.keys(data).filter(k=>!/__\d+$/.test(k)).forEach(key=>{let i=1;while(typeof data[key+'__'+i]==='string'){data[key]=String(data[key])+data[key+'__'+i];i++;}});
  const draft={version:1,demo:false,people:{kai:'凱',han:'涵'},expenses:[],incomes:[],categories:[],settlements:{},config:{year:Number(data.hh_cur_year)||new Date().getFullYear(),month:ui?.month||new Date().getMonth()+1,budget:0,cloudUrl:''}},incomeMap=new Map();let found=false;
  for(const [key,value]of Object.entries(data)){const match=key.match(/^hh_(exp|inc)_(\d{4})$/);if(!match)continue;found=true;const records=typeof value==='string'?JSON.parse(value):value;if(!Array.isArray(records))throw Error('收支資料格式不正確。');for(const r of records){const id=(match[1]==='exp'?draft.expenses:draft.incomes).length+1;if(match[1]==='inc')incomeMap.set(match[2]+':'+r.id,id);const validated=validateRecord(r,match[1]==='exp',id);draft[match[1]==='exp'?'expenses':'incomes'].push(validated);}}
  if(!found)throw Error('找不到收支資料。請選擇原帳本匯出的 JSON 備份。');
  if(data.hh_cats){const cats=typeof data.hh_cats==='string'?JSON.parse(data.hh_cats):data.hh_cats;if(Array.isArray(cats))draft.categories=cats;}
  Object.entries(data).forEach(([key,value])=>{const match=key.match(/^hh_spaid_(\d{4})_(\d{2})$/);if(match&&String(value)==='1'){const incomeId=incomeMap.get(match[1]+':'+data['hh_spaid_id_'+match[1]+'_'+match[2]])||draft.incomes.find(i=>i.date.startsWith(match[1]+'-'+match[2])&&i.source==='涵還款')?.id,inc=draft.incomes.find(i=>i.id===incomeId);if(inc){const k=match[1]+'-'+match[2];inc.settlementKey=k;draft.settlements[k]={amount:inc.amount,from:'han',to:'kai',date:inc.date,incomeId};}}});return validateState(draft);
}
function replaceWithImport(imported){const year=ui.year,month=ui.month;ui.year=imported.config.year;ui.month=imported.config.month;const ok=commit(s=>{const localUrl=s.config.cloudUrl;Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,imported);s.demo=false;s.config.cloudUrl=localUrl;});if(!ok){ui.year=year;ui.month=month;return;}resetFilters();render();toast('帳本匯入好了，熟悉的日常都在。');}
async function importFile(file){if(!file)return;if(file.size>25e6){toast('這份檔案太大了，請使用 25 MB 以下的 JSON 備份。');return;}try{const imported=parseBackup(JSON.parse(await file.text())),years=[...new Set([...imported.expenses,...imported.incomes].map(e=>e.date.slice(0,4)))].sort();openConfirm('把這份日常帶進來？',`找到 ${imported.expenses.length} 筆支出、${imported.incomes.length} 筆收入。\n年度：${years.join('、')||'空白帳本'}\n將替換此新帳本的資料。原本的記帳網頁不受影響，建議先匯出目前備份。`,()=>replaceWithImport(imported),'確認匯入');}catch(error){toast('匯入失敗：'+error.message);}}
function startEmpty(){openConfirm('從我們的第一筆開始？','將清空這個新帳本的所有收支與還款紀錄。\n名稱與分類會保留，原本的記帳網頁不受影響。\n如果已有重要資料，請先匯出備份。',()=>{if(commit(s=>{s.expenses=[];s.incomes=[];s.settlements={};s.demo=false;})){resetFilters();render();toast('空白的小日子，等我們慢慢填滿。');}},'清空並開始');}
function cloudPayload(){const data={hh_cats:JSON.stringify(state.categories),hh_cur_year:String(ui.year)},years=[...new Set([...state.expenses,...state.incomes].map(e=>e.date.slice(0,4)))];years.forEach(year=>{data['hh_exp_'+year]=JSON.stringify(state.expenses.filter(e=>e.date.startsWith(year+'-')));data['hh_inc_'+year]=JSON.stringify(state.incomes.filter(e=>e.date.startsWith(year+'-')));});if(!years.length){data['hh_exp_'+ui.year]='[]';data['hh_inc_'+ui.year]='[]';}for(const [key,paid]of Object.entries(state.settlements)){const [year,mm]=key.split('-');if(paid.from==='han'){data['hh_spaid_'+year+'_'+mm]='1';data['hh_spaid_id_'+year+'_'+mm]=String(paid.incomeId);}}const chunks={};for(const [key,value]of Object.entries(data)){chunks[key]=value.slice(0,8000);for(let i=8000,j=1;i<value.length;i+=8000,j++)chunks[key+'__'+j]=value.slice(i,i+8000);}return chunks;}
async function runCloud(upload){const url=state.config.cloudUrl;if(!url){toast('請先在設定中儲存獨立的雲端服務網址。');return;}if(cloudBusy)return;cloudBusy=true;render();toast(upload?'正在把日常備份到雲端…':'正在讀取雲端的日常…');try{const response=await fetch(upload?url:url+(url.includes('?')?'&':'?')+'t='+Date.now(),upload?{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'setAll',data:cloudPayload()}),signal:AbortSignal.timeout(20000)}:{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('服務回應 '+response.status);const result=await response.json();if(!result.ok)throw Error(result.error||'服務回應錯誤');if(upload)toast('雲端備份完成，多一份安心。');else{const imported=parseBackup(result.data);replaceWithImport(imported);}}catch(error){toast('同步沒有完成：'+error.message);}finally{cloudBusy=false;render();}}
function cloudAction(upload){if(!state.config.cloudUrl){toast('請先儲存獨立的同步服務網址。');return;}openConfirm(upload?'上傳至這個專屬雲端？':'載入雲端的帳本？',upload?'此新帳本的完整收支會上傳，並取代該服務的資料。請確認這是新帳本的專屬服務。':'雲端收支將取代這個新帳本的資料。建議先匯出本機備份。',()=>runCloud(upload),upload?'確認上傳':'確認載入');}
document.addEventListener('click',event=>{
  const close=event.target.closest('[data-close]');if(close){close.closest('dialog').close();return;}
  const nav=event.target.closest('[data-page]');if(nav){event.preventDefault();goPage(nav.dataset.page);return;}
  const kind=event.target.closest('.entry-kind [data-kind]');if(kind){setEntryKind(kind.dataset.kind);return;}
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=Number(button.dataset.id),type=button.dataset.kind;
  const actions={'open-menu':()=>showDialog('nav-dialog'),add:()=>openEntry(ui.page==='records'?ui.type:'expense'),'prev-month':()=>shiftMonth(-1),'next-month':()=>shiftMonth(1),'edit-entry':()=>openEntry(type,id),'delete-entry':()=>deleteEntry(type,id),'record-type':()=>{ui.type=type;resetFilters();render();},'clear-filters':()=>{resetFilters();render();},'clear-selection':()=>{ui.selection.clear();render();},'batch-date':openBatch,'prev-page':()=>{ui.pageNum--;render();},'next-page':()=>{ui.pageNum++;render();},'open-day':()=>openDay(button.dataset.date),'day-add':()=>{$('#day-dialog').close();openEntry('expense',null,ui.day);},'day-edit':()=>{$('#day-dialog').close();openEntry(type,id);},'jump-month':()=>{ui.month=Number(button.dataset.month);commit(()=>{});goPage('records');},'mark-paid':markPaid,'undo-paid':undoPaid,'new-category':newCategory,'export-json':exportJSON,'export-csv':()=>exportCSV(false),'export-year':()=>exportCSV(true),'import-json':()=>{$('#import-file').value='';$('#import-file').click();},'start-empty':startEmpty,'cloud-upload':()=>cloudAction(true),'cloud-load':()=>cloudAction(false)};actions[action]?.();
});
document.addEventListener('input',event=>{const target=event.target;if(target.id==='record-search'){ui.query=target.value;ui.selection.clear();ui.pageNum=1;render();}if(target.closest('#entry-form'))updateFormula();});
document.addEventListener('change',event=>{const target=event.target;if(target.id==='period-month')changePeriod(ui.year,Number(target.value));if(target.id==='period-year')changePeriod(Number(target.value),ui.month);if(target.id==='category-filter'||target.id==='who-filter'){ui[target.id==='category-filter'?'category':'who']=target.value;ui.selection.clear();ui.pageNum=1;render();}if(target.matches('[data-select-id]')){const id=Number(target.dataset.selectId);if(target.checked)ui.selection.add(id);else ui.selection.delete(id);render();}if(target.id==='select-all-records'){ui.selection=target.checked?new Set(getFiltered().map(e=>e.id)):new Set();render();}if(target.id==='import-file')importFile(target.files[0]);});
document.addEventListener('submit',event=>{
  if(event.target.id==='preferences-form'){event.preventDefault();const form=new FormData(event.target),kai=String(form.get('kai')).trim(),han=String(form.get('han')).trim(),budget=Number(form.get('budget'));if(!kai||!han||!Number.isFinite(budget)||budget<0)return;if(commit(s=>{s.people={kai,han};s.config.budget=budget;}))toast('帳本又更像我們一點了。');}
  if(event.target.id==='cloud-form'){event.preventDefault();const url=String(new FormData(event.target).get('cloudUrl')).trim();if(url&&!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec(?:\?.*)?$/.test(url)){toast('請填寫有效的 Google Apps Script Web App HTTPS 網址。');return;}if(commit(s=>s.config.cloudUrl=url))toast(url?'雲端網址已儲存。':'已移除雲端連接。');}
});
$('#entry-form').addEventListener('submit',saveEntry);$('#batch-form').addEventListener('submit',saveBatch);
$('#confirm-form').addEventListener('submit',async event=>{event.preventDefault();const callback=confirmCallback;confirmCallback=null;$('#confirm-dialog').close();if(callback)await callback();});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(PAGE_INFO[page]&&page!==ui.page)goPage(page);});
// Persistence and original accounting rules for the approved Little Ledger interface.
var ledgerRaw,ledgerStatus='正在確認雲端資料…';
function ledgerPrefs(){try{return JSON.parse(localStorage.getItem('ll_preferences_v2')||'{}');}catch{return {};}}
function loadState(){
 try{ledgerRaw=LedgerData.collect(localStorage);}catch{ledgerRaw={hh_cats:JSON.stringify(DEFAULT_CATEGORIES),hh_cur_year:String(new Date().getFullYear()),['hh_exp_'+new Date().getFullYear()]:'[]',['hh_inc_'+new Date().getFullYear()]:'[]'};}
 return LedgerModel.fromRaw(ledgerRaw,ledgerPrefs());
}
function ledgerBackup(label){const backup=JSON.stringify({format:'household-budget-safety',savedAt:new Date().toISOString(),label,data:ledgerRaw});const previous=localStorage.getItem('ll_safety_latest');if(previous)localStorage.setItem('ll_safety_previous',previous);localStorage.setItem('ll_safety_latest',backup);}
function ledgerStatusSet(text){ledgerStatus=text;const el=$('#save-status');if(el)el.innerHTML='<span></span>'+esc(text);const message=$('#cloud-message');if(message)message.textContent=text;}
function ledgerCheckCurrent(){let stored;try{stored=LedgerData.collect(localStorage);}catch{return;}if(LedgerData.signature(stored)!==LedgerData.signature(ledgerRaw))throw Error('另一個分頁已更新帳目，請重新整理後再操作。');}
function commit(change,{renderPage=true}={}){
 const next=structuredClone(state);change(next);next.config.year=ui.year;next.config.month=ui.month;
 const previousPrefs=localStorage.getItem('ll_preferences_v2');
 try{
  ledgerCheckCurrent();
  const raw=LedgerModel.toRaw(next,ledgerRaw),changed=LedgerData.signature(raw)!==LedgerData.signature(ledgerRaw);
  raw.hh_sync_url=next.config.cloudUrl||LedgerModel.DEFAULT_SYNC;
  const endpointChanged=raw.hh_sync_url!==(ledgerRaw.hh_sync_url||LedgerModel.DEFAULT_SYNC);
  if(changed)ledgerBackup('修改前自動備份');
  localStorage.setItem('ll_preferences_v2',JSON.stringify({people:next.people,budget:next.config.budget,month:ui.month}));
  LedgerData.replace(localStorage,raw);localStorage.setItem('hh_cur_year',String(ui.year));
  if(endpointChanged){localStorage.setItem('hh_sync_url',raw.hh_sync_url);localStorage.removeItem('ll_cloud_baseline');}
  ledgerRaw=LedgerData.collect(localStorage);state=LedgerModel.fromRaw(ledgerRaw,ledgerPrefs());
  if(changed){localStorage.setItem('ll_unsynced','1');ledgerStatusSet('已儲存於此裝置・待雲端同步');}
 }catch(error){if(previousPrefs===null)localStorage.removeItem('ll_preferences_v2');else localStorage.setItem('ll_preferences_v2',previousPrefs);toast('儲存未完成，原帳目已保留：'+error.message);return false;}
 if(renderPage)render();return true;
}
function personalTotals(records){return LedgerModel.personalTotals(records);}
function calcSettle(records){return LedgerModel.calcSettle(records);}
function settlementBalance(key=monthKey()){return state.settlements[key]?0:calcSettle(state.expenses.filter(e=>e.date.startsWith(key+'-')));}
function metrics(year=false){
 const prefix=String(ui.year),ex=state.expenses.filter(e=>year?e.date.startsWith(prefix+'-'):inMonth(e)),inc=state.incomes.filter(e=>year?e.date.startsWith(prefix+'-'):inMonth(e)),spend=sum(ex,total),income=sum(inc,e=>e.amount),balance=settlementBalance(),due=year?sum(Array.from({length:12},(_,i)=>`${ui.year}-${String(i+1).padStart(2,'0')}`),k=>Math.abs(settlementBalance(k))):Math.abs(balance);
 return `<section class="metrics" aria-label="${year?'全年':'本月'}收支摘要">${metric(year?'全年支出':'本月支出',spend,'↗',`${ex.length} 筆被好好記下的日常`)}${metric(year?'全年收入':'本月收入',income,'↙',`${inc.length} 筆收入，包含已記錄的還款`)}${metric(year?'全年收支差額':'本月收支差額',income-spend,'+',income>=spend?'多一點餘裕，留給喜歡的生活':'本期支出高於收入',income>=spend)}${metric('待分帳金額',due,'♡',year?'各月份尚未結清金額合計':Math.abs(balance)<.01?'本月帳目已平':`${esc(person(balance>0?'kai':'han'))} → ${esc(person(balance>0?'han':'kai'))}`)}</section>`;
}
function saveEntry(event){
 event.preventDefault();const form=$('#entry-form'),v=new FormData(form),date=String(v.get('date')),name=String(v.get('name')).trim(),price=parseAmount(v.get('priceExpr')),expense=ui.entryKind==='expense',qty=Number(v.get('qty')),taxes=['gst','pst'].map(k=>String(v.get(k)).trim()?parseAmount(v.get(k)):0),error=$('#entry-error');
 if(!validDate(date)||!name||price===null||price<=0){error.textContent='請填寫有效日期、項目與大於 0 的金額。';return;}
 if(expense&&(!Number.isFinite(qty)||qty<=0||taxes.some(n=>n===null||n<0))){error.textContent='請檢查數量與稅額。';return;}
 const collection=expense?'expenses':'incomes',existing=state[collection].find(e=>e.id===ui.editingId);
 if(existing?.settlementKey){error.textContent='這筆還款請從「兩人分帳」取消後重新記錄。';return;}
 // Editing another field must not recalculate or round the saved unit price/amount.
 const expr=String(v.get('priceExpr')).trim(),unchanged=existing&&expr===String(expense?(existing.priceExpr||existing.price):existing.amount),amount=unchanged?(expense?existing.price:existing.amount):price;
 const id=existing?.id||nextId(state[collection]);
 const taxValue=n=>existing&&String(v.get(n?'pst':'gst'))===String(existing[n?'pst':'gst']||'')?(existing[n?'pst':'gst']||0):taxes[n];
 const record=expense?{...existing,id,date,name,price:amount,priceExpr:expr,qty,cat:String(v.get('cat')),who:String(v.get('who')),paidBy:String(v.get('paidBy')),gst:existing?taxValue(0):0,pst:existing?taxValue(1):0,note:String(v.get('note')).trim()}:{...existing,id,date,source:name,amount,who:String(v.get('incomeWho'))};
 const oldYear=ui.year,oldMonth=ui.month;ui.year=Number(date.slice(0,4));ui.month=Number(date.slice(5,7));
 if(commit(s=>{const idx=s[collection].findIndex(e=>e.id===id);if(idx>=0)s[collection][idx]=record;else s[collection].push(record);if(expense&&!existing)for(let n=0;n<2;n++)if(taxes[n]>0)s.expenses.push({id:nextId(s.expenses),date,name:n?'PST':'GST',qty:1,priceExpr:String(taxes[n]),price:taxes[n],cat:n?'PST':'GST',who:record.who,paidBy:record.paidBy,gst:0,pst:0,note:''});},{renderPage:false})){$('#entry-dialog').close();resetFilters();render();toast(existing?'這一筆，已經改好了。':'又一筆日常，好好收進帳本了。');}else{ui.year=oldYear;ui.month=oldMonth;error.textContent='儲存未完成，請重試。';}
}
function markPaid(){
 const due=settlementBalance(),key=monthKey();if(Math.abs(due)<.01||state.settlements[key])return;
 const from=due>0?'kai':'han',to=from==='kai'?'han':'kai',amount=Math.round(Math.abs(due)*100)/100;
 openConfirm('這筆轉帳，已經完成了嗎？',`${person(from)} → ${person(to)}\nCAD ${money(amount)}\n這裡只記錄實際還款，不會替你轉帳。`,()=>{if(commit(s=>{const incomeId=nextId(s.incomes),date=key+'-'+String(new Date(ui.year,ui.month,0).getDate()).padStart(2,'0');s.settlements[key]={amount,from,to,date,incomeId};s.incomes.push({id:incomeId,date,source:person(from)+'還款',who:to,amount,settlementKey:key,_derivedSettlementKey:true});}))toast('還款已記錄。');},'已轉帳，記下還款');
}
function exportJSON(){const copy={...ledgerRaw};delete copy.hh_sync_url;download(JSON.stringify(copy,null,2),`家庭帳本_${localDate()}.json`,'application/json;charset=utf-8');toast('所有年度的完整原始帳目已匯出。');}
function exportCSV(year=false){const filter=e=>year?e.date.startsWith(ui.year+'-'):inMonth(e),rows=[['種類','日期','項目','分類','歸屬','付款人','數量','單價','GST','PST','合計','備註','原始金額算式','編號']];state.expenses.filter(filter).sort((a,b)=>a.date.localeCompare(b.date)).forEach(e=>rows.push(['支出',e.date,e.name,e.cat,e.who==='shared'?'共同':person(e.who),person(e.paidBy),e.qty,e.price,e.gst||0,e.pst||0,total(e),e.note||'',e.priceExpr,e._ledgerId]));state.incomes.filter(filter).sort((a,b)=>a.date.localeCompare(b.date)).forEach(e=>rows.push([isTransfer(e)?'還款':'收入',e.date,e.source,'',person(e.who),'','','','','',e.amount,'','',e._ledgerId]));download('\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),`一起存_${year?ui.year:monthKey()}.csv`,'text/csv;charset=utf-8');toast('明細已匯出，可以用 Excel 開啟。');}
function ledgerApply(raw,clean=true){
 const checked=LedgerData.validate(raw),hadYear=localStorage.getItem('hh_cur_year');ledgerCheckCurrent();ledgerBackup('載入或匯入前自動備份');LedgerData.replace(localStorage,checked);
 if((!hadYear||!clean)&&/^\d{4}$/.test(checked.hh_cur_year||'')){ui.year=Number(checked.hh_cur_year);localStorage.setItem('hh_cur_year',String(ui.year));}
 ledgerRaw=LedgerData.collect(localStorage);state=LedgerModel.fromRaw(ledgerRaw,ledgerPrefs());resetFilters();
 if(clean){localStorage.setItem('ll_cloud_baseline',LedgerData.signature(ledgerRaw));localStorage.removeItem('ll_unsynced');}else localStorage.setItem('ll_unsynced','1');render();
}
async function importFile(file){if(!file)return;try{let input=JSON.parse(await file.text());if(input.format==='household-budget-safety')input=input.data;const raw=LedgerData.validate(input),view=LedgerModel.fromRaw(raw);openConfirm('把這份日常帶進來？',`找到 ${view.expenses.length} 筆支出、${view.incomes.length} 筆收入。\n目前裝置帳目會先自動備份，雲端不會自動覆蓋。`,()=>{try{ledgerApply(raw,false);ledgerStatusSet('已匯入本機・待雲端同步');toast('完整帳目已匯入。');}catch(e){toast('匯入未完成：'+e.message);}},'確認匯入');}catch(error){toast('匯入失敗，原帳目未更改：'+error.message);}}
function cloudUrl(){return localStorage.getItem('hh_sync_url')||LedgerModel.DEFAULT_SYNC;}
async function readCloud(){const url=cloudUrl(),response=await fetch(url+(url.includes('?')?'&':'?')+'t='+Date.now(),{signal:AbortSignal.timeout(25000)});if(!response.ok)throw Error('雲端服務回應 '+response.status);const json=await response.json();if(!json.ok)throw Error(json.error||'雲端回應錯誤');return LedgerData.validate(json.data);}
async function runCloud(upload){
 if(cloudBusy)return;cloudBusy=true;render();ledgerStatusSet(upload?'正在同步到雲端…':'正在載入雲端…');
 try{
  const remote=await readCloud();
  if(upload){
   ledgerCheckCurrent();
   const local=LedgerData.validate(ledgerRaw),signature=LedgerData.signature(local),remoteSig=LedgerData.signature(remote),baseline=localStorage.getItem('ll_cloud_baseline');
   if(remoteSig!==signature&&(!baseline||remoteSig!==baseline))throw Error('另一台裝置已更新雲端；已保留本機資料，請先匯出備份並載入雲端確認。');
   ledgerBackup('雲端同步前自動備份');const response=await fetch(cloudUrl(),{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'setAll',data:LedgerData.chunks(local)}),signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('上傳回應 '+response.status);const result=await response.json();if(!result.ok)throw Error(result.error||'上傳未完成');
   if(LedgerData.signature(await readCloud())!==signature)throw Error('雲端回讀與本機不一致，備份已保留。');
   localStorage.setItem('ll_cloud_baseline',signature);
   if(LedgerData.signature(LedgerData.collect(localStorage))===signature){localStorage.removeItem('ll_unsynced');ledgerStatusSet('✓ 雲端同步完成・手機可查看');}else ledgerStatusSet('同步期間有新變更・請再同步一次');
  }else{ledgerApply(remote);ledgerStatusSet('✓ 已載入雲端最新帳目');}
  toast(upload?'雲端同步完成，資料核對一致。':'已載入雲端最新帳目。');
 }catch(error){ledgerStatusSet('同步尚未完成・'+error.message);toast(error.message);}finally{cloudBusy=false;render();}
}
function cloudAction(upload){if(upload)return runCloud(true);openConfirm('載入雲端的帳本？','目前本機帳目會先自動備份，再載入雲端最新資料。',()=>runCloud(false),'確認載入');}
function ledgerDownloadSafety(){const text=localStorage.getItem('ll_safety_latest')||localStorage.getItem('ll_migration_backup_v1');if(!text){toast('尚無自動備份。');return;}download(text,'家庭帳本_自動備份.json','application/json;charset=utf-8');}
function ledgerRestoreSafety(){const text=localStorage.getItem('ll_safety_latest');if(!text){toast('尚無自動備份。');return;}const backup=JSON.parse(text);openConfirm('還原最近一次自動備份？',backup.label+'\n目前帳目也會先備份；不會自動覆蓋雲端。',()=>{ledgerApply(backup.data,false);ledgerStatusSet('已還原本機備份・待雲端同步');},'確認還原');}
function ledgerMonthSettled(){const key='hh_settled_'+String(ui.month).padStart(2,'0');ledgerBackup('變更結算標記前');const value=ledgerRaw[key]==='1'?'0':'1';localStorage.setItem(key,value);ledgerRaw[key]=value;localStorage.setItem('ll_unsynced','1');ledgerStatusSet('已儲存於此裝置・待雲端同步');render();}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(action==='download-safety')ledgerDownloadSafety();if(action==='restore-safety')ledgerRestoreSafety();if(action==='month-settled')ledgerMonthSettled();});
document.addEventListener('ledger:render',()=>ledgerStatusSet(ledgerStatus));
async function ledgerStartup(){
 try{
  if(state.expenses.length+state.incomes.length&&!localStorage.getItem('ll_migration_backup_v1'))localStorage.setItem('ll_migration_backup_v1',JSON.stringify({format:'household-budget-safety',label:'完整 UI 更新前帳目',savedAt:new Date().toISOString(),data:ledgerRaw}));
  const remote=await readCloud(),r=LedgerData.signature(remote),l=LedgerData.signature(ledgerRaw),baseline=localStorage.getItem('ll_cloud_baseline');
  if(r===l){localStorage.setItem('ll_cloud_baseline',l);localStorage.removeItem('ll_unsynced');ledgerStatusSet('✓ 本機與雲端資料一致');}
  else if(!state.expenses.length&&!state.incomes.length||!localStorage.getItem('ll_unsynced')&&baseline===l){ledgerApply(remote);ledgerStatusSet('✓ 已載入雲端最新帳目');}
  else ledgerStatusSet('本機與雲端有差異・已保留本機，請先備份再確認同步');
 }catch(error){ledgerStatusSet('目前使用本機帳目・'+error.message);}
}

render();ledgerStartup();
